import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CYjxsSA2.js";const b=JSON.parse('{"title":"代理与网络出口","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/proxy.md","filePath":"advanced/proxy.md"}'),o={name:"advanced/proxy.md"};function n(l,t,s,h,i,c){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="代理与网络出口" tabindex="-1">代理与网络出口 <a class="header-anchor" href="#代理与网络出口" aria-label="Permalink to &quot;代理与网络出口&quot;">​</a></h1><p>平台提供两套出口控制：<strong>全局代理</strong>（统一单一出口）与<strong>代理池</strong>（多出口轮换 + 故障转移）。</p><h2 id="全局代理" tabindex="-1">全局代理 <a class="header-anchor" href="#全局代理" aria-label="Permalink to &quot;全局代理&quot;">​</a></h2><p><strong>系统配置 → 全局代理 → 全局 HTTP 代理</strong>：指定一个代理节点作为当前出口，平台内出站请求统一走它。</p><h2 id="代理池" tabindex="-1">代理池 <a class="header-anchor" href="#代理池" aria-label="Permalink to &quot;代理池&quot;">​</a></h2><p>代理池维护多个出口，支持编排与自动切换。</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>协议</td><td>HTTP / HTTPS / SOCKS5 / SOCKS4</td></tr><tr><td>轮换策略</td><td>轮询、随机、按时间、按请求数</td></tr><tr><td>节点串联</td><td>多个节点可串成代理链</td></tr><tr><td>连通性检测</td><td>记录延迟与存活状态</td></tr></tbody></table><p>平台维护两个池：</p><table tabindex="0"><thead><tr><th>实例</th><th>用途</th></tr></thead><tbody><tr><td><strong>全局池</strong></td><td>除大模型外的所有流量</td></tr><tr><td><strong>Agent 池</strong></td><td>军团遭遇 WAF 封禁时的故障转移出口</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">只加节点不开开关是无效的</p><p>启用条件是「开关已打开 <strong>且</strong> 链上至少有一个节点」，两个条件缺一，流量都不会走代理。</p></div><h2 id="按功能域路由" tabindex="-1">按功能域路由 <a class="header-anchor" href="#按功能域路由" aria-label="Permalink to &quot;按功能域路由&quot;">​</a></h2><p>在<strong>代理路由</strong>里可以为不同功能单独指定出口：智能体、云上综合、目录扫描、大模型、消息通知、端口扫描、空间测绘、漏洞测绘等。默认跟随全局设置。</p><p>典型组合：</p><table tabindex="0"><thead><tr><th>场景</th><th>配置</th></tr></thead><tbody><tr><td>统一走公司出口</td><td>全局代理指定一个节点</td></tr><tr><td>防 WAF 封 IP</td><td>代理池配置 3–5 个节点 + 按请求轮换，保持 Agent 故障转移开启</td></tr><tr><td>扫描直连、云上走代理</td><td>只为「云上综合」单独指定出口</td></tr><tr><td>多级跳板</td><td>把多个节点串成一条链</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>修改设置或调整链会重置轮换状态</li><li>代理节点需要认证时，先确认凭据格式被支持</li><li>连通性检测是主动外连，目标不可达时节点会被判定为不可用</li></ul>',16)])])}const _=a(o,[["render",n]]);export{b as __pageData,_ as default};
